def try_rule(A,O,N=None):
    A=np.array(A); O=np.array(O); n=A.shape[0]; N=N or O.shape[0]
    ys,xs=np.where(A!=0); B=A[ys.min():ys.max()+1,xs.min():xs.max()+1]; H,W=B.shape
    vals,cnt=np.unique(A,return_counts=True); bg=int(vals[np.argmax(cnt)])
    bvals,Bcnt=np.unique(B.flatten(),return_counts=True); bbg=int(bvals[np.argsort(-Bcnt)[1]])  # second color = bg in B coords
