import numpy as np
# Test diagonal ray hypothesis cleanly: for each cell of output canvas (2n x 2n), walk up-left
# from that cell over the FULL INPUT (uncropped, n x n) with wrap mod n, first non-bg cell's value.
def ray(A,n,direction='ul'):
    vals,cnt=np.unique(A,return_counts=True); bg=int(vals[np.argmax(cnt)])
    N=A.shape[0]; out=np.zeros((2*N,2*N),dtype=int)
    if direction=='ul':
        def step(i,j): return (i-1)%N,(j-1)%N
    elif direction=='ur':
        def step(i,j): return (i-1)%N,(j+1)%N
    elif direction=='dl':
        def step(i,j): return (i+1)%N,(j-1)%N
    elif direction=='dr':
        def step(i,j): return (i+1)%N,(j+1)%N
    for r in range(2*N):
        for c in range(2*N):
            i,j=r,c
            while True:
                i,j=step(i,j)
                if A[i][j]!=bg:
                    out[r][c]=A[i][j]; break
    return out
