def check_diag(O,I,N,p):
    g={}
    bad=0
    for r in range(2*N):
        for c in range(2*N):
            if O[r][c]==0: continue
            k=(c-r)%p
            if g.get(k)!=O[r][c]: bad+=1
            g[k]=O[r][c]
    return 'consistent' if bad==0 else ('%.1f%%'%(bad/4.0))
print('d7 diff:',[check_diag(O7,I7,15,p) for p in range(3,20)])
print('d7 sum :', [check_diag(O7,I7,15,p) for p in range(3,20)])

