def analyze(n):
    I=G[f'Demo pair {n} input']; O=G[f'Demo pair {n} output']
    rows=[i for i,r in enumerate(I) if any(r)]; cols=[j for j,x in [(a,b) for a,r in enumerate(I) for b in r] if x!=0]
    r0,r1=min(rows),max(rows); c0,c1=min(cols),max(cols)
    blk=[[I[i][j] for j in range(c0,c1+1)] for i in range(r0,r1+1)]
